def update_json_with_translations():
    with open(json_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    
    for item in data:
        item_id = item.get('id')
        if item_id in translations:
            item.update(translations[item_id])
    
    with open(json_path, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"Updated {len(data)} items in {json_path}")

if __name__ == "__main__":
    update_json_with_translations()
